local classes = {}

classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = {},
  matchers = { { status = 403 } },
  fields = { "code", "message" },
})
classes.NotEntitled = errors.define({
  tag = "NotEntitled",
  categories = {},
  matchers = { { status = 403, message = { includes = "not entitled" } } },
  fields = { "code", "message" },
})
classes.PolicyNotFound = errors.define({
  tag = "PolicyNotFound",
  categories = {},
  matchers = { { status = 404, message = { includes = "Could not find Policy" } } },
  fields = { "code", "message" },
})
classes.PolicyQuotaExceeded = errors.define({
  tag = "PolicyQuotaExceeded",
  categories = {},
  matchers = {
    {
      status = 400,
      message = {
        includes = "exceeded the maximum number of rules in the phase http_response_page_shield",
      },
    },
  },
  fields = { "code", "message" },
})

